const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const enc=encodeURIComponent;
let state={items:[],user:null},pageToken=0;
const main=$('#main');
const money=n=>n===null||n===undefined?'Tarif à confirmer':n===0?'Gratuit':new Intl.NumberFormat('fr-FR').format(n)+' FCFA';
const date=x=>x?new Date(typeof x==='number'?x*1000:x).toLocaleDateString('fr-FR'):'À confirmer';
const domains=['Droit OHADA','Droit des affaires','Droit commercial','Droit des sociétés','Droit des contrats','Droit immobilier','Droit du travail','Droit fiscal','Droit administratif','Droit pénal','Procédure pénale','Procédures civiles et commerciales','Recouvrement','Voies d’exécution','LBC/FT et conformité','Droit numérique','Rédaction juridique','Méthodologie juridique','Pratique professionnelle'];
const categories={formations:['Toutes les formations','Formations à la une','Nouvelles formations','Formations gratuites','Parcours professionnels','Classes virtuelles','Webinaires','Masterclass','Domaines de formation'],boutique:['Tous les documents','Contrats','Actes juridiques','Actes judiciaires',"Documents d’entreprise",'Conformité','Guides pratiques'],bibliotheque:['Tous les documents','Textes juridiques','OHADA','Jurisprudence','Ouvrages','Articles scientifiques','Mémoires et travaux','Fiches de cours','Supports pédagogiques','Guides professionnels'],blog:['Tous les articles','Droit OHADA','Droit des affaires','Droit immobilier','Droit du travail','Contrats','Procédures','Recouvrement','Voies d’exécution','Fiscalité','LBC/FT','Droit numérique','Vie universitaire'],etudiants:['Fiches de cours','Fiches de révision','Méthodologie','Cas pratiques','Commentaires d’arrêt','Dissertation','Préparation aux examens','Ressources universitaires','Orientation professionnelle','Formations pour étudiants'],professionnels:['Avocats','Commissaires de Justice','Notaires','Juristes','Magistrats','Experts','Responsables juridiques','Responsables conformité','Entrepreneurs','Administrations'],entreprises:['Formation en entreprise','Formation des équipes','Droit du travail','Contrats','Gouvernance','Conformité','LBC/FT','Prévention des risques','Documentation juridique','Veille juridique','Demander un devis'],evenements:['Calendrier','Webinaires','Conférences','Masterclass','Classes virtuelles','Formations en présentiel','Événements passés','Replays'],apropos:['Qui sommes-nous ?','Notre mission','Notre vision','Nos valeurs','Notre équipe','Nos formateurs','Nos partenaires','Nos domaines d’expertise','Pourquoi LEX ASSOCIÉS ?'],contact:['Nous contacter','FAQ','Newsletter']};
const labels={formations:'Formations',boutique:'Boutique',bibliotheque:'Bibliothèque',blog:'Blog',etudiants:'Étudiants',professionnels:'Professionnels',entreprises:'Entreprises',evenements:'Événements',apropos:'À propos',contact:'Contact'};
const domainSubs={'Droit OHADA':['Droit commercial général','Sociétés commerciales','GIE','Sûretés','Recouvrement','Voies d’exécution','Procédures collectives','Arbitrage','Médiation'],'Droit des affaires':['Création d’entreprise','Vie de l’entreprise','Gouvernance','Responsabilité des dirigeants','Contentieux','Contrats commerciaux','Opérations commerciales'],'Droit des contrats':['Formation du contrat','Clauses','Exécution','Inexécution','Résiliation','Responsabilité','Contrats commerciaux','Contrats de prestation','Partenariats','Confidentialité'],'Droit immobilier':['Bail d’habitation','Bail professionnel','Renouvellement','Congé','Expulsion','Loyers impayés','Vente immobilière','Gestion immobilière','Contentieux immobilier'],'Procédures civiles et commerciales':['Procédure civile','Procédure commerciale','Référé','Requête','Assignation','Signification','Délais','Voies de recours','Exécution des décisions'],'Recouvrement':['Recouvrement amiable','Mise en demeure','Injonction de payer','Recouvrement judiciaire','Exécution','Suivi des créances','Cas pratiques'],'Voies d’exécution':['Saisie-attribution','Saisie conservatoire','Saisie-vente','Saisie immobilière','Saisie des rémunérations','Saisie des droits sociaux','Conversion','Contestations'],'LBC/FT et conformité':['KYC','Identification','Bénéficiaire effectif','Classification des risques','PPE','Surveillance','DOS/DSTE','SFC','Conservation','Contrôle interne','Manuel LBC/FT','Audit conformité'],'Rédaction juridique':['Requête','Assignation','Mise en demeure','Contrat','Convention','Procès-verbal','Correspondance juridique','Conclusions','Actes professionnels'],'Méthodologie juridique':['Cas pratique','Dissertation','Commentaire d’arrêt','Commentaire de texte','Fiche d’arrêt','Recherche juridique','Analyse juridique','Syllogisme juridique']};
