function icon(type='scale'){const p={scale:'M12 3v17M5 21h14M3 7h18M5 7l-4 8h8L5 7zm14 0l-4 8h8l-4-8z',book:'M12 5v16M12 5C8 2 4 2 2 3v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-4-1-7-1-10 2z',cap:'M1 8l11-5 11 5-11 5L1 8zm4 3v6c4 4 10 4 14 0v-6M23 8v9',file:'M6 2h9l5 5v15H6V2zm9 0v6h5M9 12h8M9 16h8',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm8 0a3 3 0 1 0 0-6M1 21v-3c0-5 14-5 14 0v3M18 14c4 0 5 2 5 5v2',case:'M3 7h18v14H3V7zm5 0V3h8v4M3 12h18M10 12v3h4v-3',play:'M8 5l12 7-12 7V5z'};return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"> <path d="${p[type]||p.scale}"/></svg>`;}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let b;try{b=await r.json();}catch{throw Error('Le serveur de la plateforme ne répond pas.');}if(!r.ok)throw Error(b.error||'Une erreur est survenue.');return b;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function routeLink(key,sub){if(key==='contact'&&sub==='FAQ')return '#/faq';if(key==='contact'&&sub==='Newsletter')return '#/newsletter';if(key==='apropos'&&sub==='Nos formateurs')return '#/formateurs';return '#/'+key+(sub?'?categorie='+enc(sub):'');}
function rubriqueLink(key,sub){if(/^Tous|^Toutes/.test(sub))return '#/'+key;if(key==='entreprises'&&sub==='Demander un devis')return '#/contact?objet=Demande%20de%20devis';if(key==='entreprises'&&sub==='Veille juridique')return '#/veille';if(key==='etudiants'&&sub==='Formations pour étudiants')return '#/formations?public='+enc('Étudiants');return routeLink(key,sub);}
function rubriques(key,selected=''){return `<nav class="rubriques" aria-label="Rubriques ${labels[key]}"><h2>Explorer ${key==='professionnels'?'votre profession':'les rubriques'}</h2><div class="rubrique-grid">${categories[key].map(sub=>`<a href="${rubriqueLink(key,sub)}" ${sub===selected||(!selected&&/^Tous|^Toutes/.test(sub))?'aria-current="page"':''}><span>${esc(sub)}</span><span aria-hidden="true">→</span></a>`).join('')}</div></nav>`;}
function shell(){ $('#header').innerHTML=`<div class="wrap header-main"><a class="logo" href="#/" aria-label="LEX ASSOCIÉS, accueil"><img src="/assets/logo-lex-associes.png" alt="LEX ASSOCIÉS"></a><div class="header-tools"><a href="#/recherche">Recherche juridique</a><a href="#/compte">${state.user?'Mon compte':'Connexion'}</a><a href="#/panier">Panier</a><a class="btn" href="#/contact?objet=Rendez-vous">Prendre rendez-vous</a><button class="mobile-menu" aria-label="Ouvrir le menu" aria-expanded="false">☰</button></div></div><div class="nav-row"><nav class="wrap nav" aria-label="Navigation principale"><a href="#/">Accueil</a>${Object.entries(categories).map(([k,subs])=>k!=='contact'?`<a href="#/${k}">${labels[k]}</a>`:`<details><summary>${labels[k]}</summary><div class="dropdown">${k==='contact'?'':`<a href="#/${k}">Découvrir ${labels[k].toLowerCase()}</a>`}${subs.map(s=>`<a href="${routeLink(k,s)}">${s}</a>`).join('')}</div></details>`).join('')}<a class="mobile-only" href="#/compte">Mon compte</a><a class="mobile-only" href="#/panier">Panier</a><a class="mobile-only" href="#/recherche">Recherche juridique</a></nav></div>`;
$('#footer').innerHTML=`<div class="wrap footer-grid"><div class="footer-brand"><a href="#/"><img class="footer-logo" src="/assets/logo-lex-associes.png" alt="LEX ASSOCIÉS"></a><p>Apprendre. Comprendre. Pratiquer.</p><a href="#/contact">Contacter l’équipe</a></div>${[['Plateforme',[['Accueil',''],['Formations','formations'],['Boutique','boutique'],['Bibliothèque','bibliotheque'],['Blog','blog'],['Événements','evenements'],['LEX ASSOCIÉS LIVE','live'],['Veille juridique','veille']]],['Communauté',[['Étudiants','etudiants'],['Professionnels','professionnels'],['Entreprises','entreprises'],['Formateurs','formateurs'],['Abonnements','abonnements']]],['Informations',[['À propos','apropos'],['Notre équipe','apropos?categorie=Notre%20%C3%A9quipe'],['Contact','contact'],['FAQ','faq'],['Newsletter','newsletter'],['Partenaires','apropos?categorie=Nos%20partenaires']]],['Juridique',[['Conditions générales','juridique?type=Conditions%20générales'],['Confidentialité','juridique?type=Confidentialité'],['Conditions de vente','juridique?type=Conditions%20de%20vente'],['Mentions légales','juridique?type=Mentions%20légales'],['Politique des cookies','juridique?type=Cookies']]]].map(([h,links])=>`<div><h3>${h}</h3>${links.map(([t,url])=>`<a href="#/${url}">${t}</a>`).join('')}</div>`).join('')}</div><div class="wrap footer-bottom"><span>© 2026 LEX ASSOCIÉS. Tous droits réservés.</span><span class="site-credit">Site web créé par <a href="https://www.zematechnologies.com" target="_blank" rel="noopener noreferrer">ZEMA TECHNOLOGIES</a></span></div>`;
$('.mobile-menu').onclick=()=>{const open=$('.nav-row').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',open);};$$('header details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)$$('header details').forEach(x=>{if(x!==d)x.open=false;});}));
}
const items=(kind)=>{const list=state.items.filter(i=>i.kind===kind);return kind==='plan'?list.sort((a,b)=>['Gratuit','Essentiel','Professionnel','Premium','Entreprise'].indexOf(a.title)-['Gratuit','Essentiel','Professionnel','Premium','Entreprise'].indexOf(b.title)):list;};
const button=(text,url,cls='')=>`<a class="btn ${cls}" href="${url}">${text}</a>`;
const title=(eyebrow,h,desc='')=>`<div class="section-title"><div class="eyebrow">${eyebrow}</div><h2>${h}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
const banner=(h,desc='')=>`<div class="page-banner"><div class="wrap"><div class="breadcrumb"><a href="#/">Accueil</a> / ${esc(h)}</div><h1>${esc(h)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div></div>`;
const empty=(h='Les contenus arrivent prochainement.',p='Le cabinet publiera ici les ressources validées pour cet espace.')=>`<div class="empty"><h3>${h}</h3><p>${p}</p>${button('Contacter l’équipe','#/contact','outline')}</div>`;
function card(i){const course=i.kind==='formation',article=i.kind==='article';return `<article class="card">${i.image?`<img class="card-photo" src="${safeUrl(i.image)}" alt="" loading="lazy">`:''}<div class="body"><div><span class="tag">${esc(i.category||i.kind)}</span>${i.demo?'<span class="sample">Aperçu</span>':''}</div><h3><a href="#/contenu/${enc(i.id)}">${esc(i.title)}</a></h3><p>${esc(i.description||'')}</p>${course?`<div class="card-meta"><span>${esc(i.level||'Tous niveaux')}</span><span>${esc(i.duration||'Durée à préciser')}</span><span>${(i.modules||[]).length} modules</span><span>${esc(i.trainer||'Formateur à confirmer')}</span></div>`:article?`<div class="card-meta"><span>${esc(i.author||'LEX ASSOCIÉS')}</span><span>${esc(i.reading||'Dossier')}</span></div>`:''}<div class="card-end">${['formation','document'].includes(i.kind)?`<span class="price">${money(i.price)}</span>`:''}<a class="text-link" href="#/contenu/${enc(i.id)}">${course?'Voir la formation':article?'Lire l’article':'Découvrir'}</a></div></div></article>`;}
function safeUrl(s){if(s?.startsWith('assets/'))s='/'+s;return /^(https:\/\/|\/?assets\/|\/api\/file\/)/.test(s||'')?esc(s):'';}
function plans(){return `<div class="plans">${items('plan').map(i=>`<article class="plan"><div class="eyebrow">LEX ASSOCIÉS</div><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p><p class="price">${money(i.price)}</p>${button(i.price===0?'Créer mon compte':'Découvrir l’offre',i.price===0?'#/inscription':'#/contenu/'+i.id,'outline')}</article>`).join('')}</div>`;}
function newsletter(){return `<section class="section newsletter"><div class="wrap two-col"><div><div class="eyebrow">NEWSLETTER LEX ASSOCIÉS</div><h2>Le droit directement<br>dans votre boîte mail.</h2><p>Choisissez les sujets qui vous intéressent pour suivre les publications et les formations du cabinet.</p></div><form data-form="newsletter"><div class="inline-form"><input name="name" placeholder="Votre nom" aria-label="Votre nom" required><input name="email" type="email" placeholder="Votre e-mail" aria-label="Votre e-mail" required></div><div class="interests">${['Droit OHADA','Droit des affaires','Immobilier','Procédures','LBC/FT','Droit du travail','Formations','Actualités juridiques'].map(x=>`<label><input type="checkbox" name="interest" value="${x}">${x}</label>`).join('')}</div><label class="consent"><input name="consent" type="checkbox" required>J’accepte que mon adresse soit utilisée pour la newsletter LEX ASSOCIÉS. Je peux demander mon désabonnement auprès du cabinet.</label><button class="btn" type="submit">M’inscrire à la newsletter</button><div class="feedback" role="status"></div></form></div></section>`;}
function home(){main.innerHTML=`<section class="hero"><div class="wrap"><div class="hero-content"><h1><span>LEX</span> ASSOCIÉS</h1><h2>Apprendre. Comprendre.<br>Pratiquer.</h2><p>La plateforme juridique dédiée à la formation, à la documentation et à la pratique du droit en Côte d’Ivoire et dans l’espace OHADA.</p><div class="actions">${button('Découvrir nos formations','#/formations')}${button('Explorer la bibliothèque','#/bibliotheque','outline')}</div></div></div><div class="hero-dots" aria-hidden="true"><span></span><span></span><span></span></div></section>
<section class="section compact"><div class="wrap">${title('NOS FORMATIONS & RESSOURCES','Un seul espace pour apprendre et pratiquer le droit.')}<div class="spaces">${[['cap','Formations','Apprendre et développer ses compétences.','formations'],['book','Bibliothèque','Rechercher et consulter des ressources juridiques.','bibliotheque'],['file','Boutique','Acheter des modèles et documents professionnels.','boutique'],['scale','Blog','Comprendre l’actualité et la pratique du droit.','blog'],['users','Espace professionnels','Accéder aux outils destinés aux professionnels.','professionnels']].map(([ic,t,p,r])=>`<a class="space-card" href="#/${r}"><span class="icon">${icon(ic)}</span><h3>${t}</h3><p>${p}</p><span class="text-link">Découvrir cet espace</span></a>`).join('')}</div></div></section>
<section class="section pale"><div class="wrap">${title('FORMATIONS À LA UNE','Développez votre pratique juridique.','Des parcours structurés pour relier les connaissances aux situations professionnelles.')}<div class="grid">${items('formation').slice(0,3).map(card).join('')}</div><div class="center">${button('Voir toutes les formations','#/formations','outline')}</div></div></section>
<div class="ribbon"><div class="wrap ribbon-grid"><div><b class="copper">Apprendre</b><span>Cours et modules</span></div><div><b class="copper">Comprendre</b><span>Textes et analyses</span></div><div><b class="copper">Pratiquer</b><span>Cas pratiques et modèles</span></div><div><b class="copper">Progresser</b><span>Parcours professionnels</span></div></div></div>
<section class="section"><div class="wrap">${title('DOMAINES DE FORMATION','Une approche juridique pluridisciplinaire')}<div class="domain-grid">${domains.map(d=>`<a class="domain" href="#/domaine/${enc(d)}">${icon()}<span>${d}</span></a>`).join('')}</div></div></section>
<section class="section pale"><div class="wrap two-col"><div><div class="eyebrow">PARCOURS PROFESSIONNELS</div><h2>Un parcours adapté<br>à votre métier.</h2><p>Organisez votre apprentissage autour des compétences utiles à votre activité.</p>${button('Explorer les parcours','#/formations?categorie=Parcours%20professionnels','outline')}</div><div class="paths">${paths.map(p=>`<a class="path-card" href="#/formations?parcours=${enc(p)}"><span class="icon">${icon('case')}</span>${p}</a>`).join('')}</div></div></section>
<section class="section"><div class="wrap two-col"><div class="collection-panel"><div class="eyebrow">BIBLIOTHÈQUE JURIDIQUE</div><h3>Les ressources du droit,<br>réunies au même endroit.</h3><p>Textes, jurisprudence, ouvrages et supports pour nourrir votre recherche.</p>${button('Explorer la bibliothèque','#/bibliotheque','light')}</div><div><div class="eyebrow">DOCUMENTATION & RECHERCHE</div><h2>Des repères pour approfondir.</h2><div class="link-list">${categories.bibliotheque.slice(1).map(s=>`<a href="${routeLink('bibliotheque',s)}">${s}</a>`).join('')}</div><form class="search-box" data-form="search"><input name="q" placeholder="Que recherchez-vous ?" aria-label="Recherche juridique"><button class="btn">Rechercher</button></form></div></div></section>
<section class="section pale"><div class="wrap">${title('BOUTIQUE JURIDIQUE','Des outils pour votre pratique quotidienne.')}<div class="grid">${items('document').slice(0,3).map(card).join('')}</div><div class="center">${button('Voir tous les documents','#/boutique','outline')}</div></div></section>
<section class="section"><div class="wrap">${title('BLOG JURIDIQUE','Actualités & éclairages')}<div class="grid">${items('article').slice(0,3).map(card).join('')}</div><div class="center">${button('Voir tous les articles','#/blog','outline')}</div></div></section>
<section class="section pale"><div class="wrap two-col"><img class="illustration" src="/assets/formation.jpg" alt="Échange entre professionnels" loading="lazy"><div><div class="eyebrow">LEX ASSOCIÉS LIVE</div><h2>Le droit se transmet<br>aussi par l’échange.</h2><p>Retrouvez les vidéos, webinaires, conférences, interviews et masterclass du cabinet.</p><div class="actions">${button('Découvrir LEX ASSOCIÉS LIVE','#/live')}${button('Voir les événements','#/evenements','outline')}</div></div></div></section>
<section class="section audiences"><div class="wrap two-col"><div><div class="eyebrow">À QUI NOUS NOUS ADRESSONS</div><h2>Des ressources adaptées<br>à vos besoins.</h2><p>Apprendre, se former et accéder aux outils qui accompagnent votre parcours.</p>${button('Contacter l’équipe','#/contact','outline')}</div><div class="audience-rows">${[['Étudiants','Cours, révisions, méthodologie et préparation aux examens.','etudiants'],['Professionnels','Documentation, formations et outils pour votre pratique.','professionnels'],['Entreprises','Formation des équipes, conformité et prévention des risques.','entreprises']].map(([t,p,r])=>`<a class="audience-row" href="#/${r}"><span class="icon">${icon('users')}</span><div><h3>${t}</h3><p>${p}</p></div></a>`).join('')}</div></div></section>
<section class="section"><div class="wrap">${title('ABONNEMENTS','Choisissez votre accès à la connaissance.')} ${plans()}<div class="center">${button('Comparer les abonnements','#/abonnements','outline')}</div></div></section>${newsletter()}<section class="cta"><div class="wrap"><div><h2>Un projet de formation ou un besoin juridique ?</h2><p>Notre équipe est à votre écoute pour vous accompagner.</p></div>${button('Prendre rendez-vous','#/contact?objet=Rendez-vous')}</div></section>`;}
function catalog(key,params){const kind={formations:'formation',boutique:'document',bibliotheque:'resource',blog:'article',evenements:'event',live:'live',veille:'watch',formateurs:'trainer'}[key];const category=params.get('categorie')||'';const name=labels[key]||{live:'LEX ASSOCIÉS LIVE',veille:'Veille juridique',formateurs:'Nos formateurs'}[key];if(key==='formations'&&category==='Domaines de formation')return domainPage();if(key==='formations'&&category==='Parcours professionnels')return pathPage();if(key==='formations'&&['Classes virtuelles','Webinaires','Masterclass'].includes(category)){catalog('evenements',params);main.insertAdjacentHTML('afterbegin',`<div class="wrap">${rubriques('formations',category)}</div>`);return;}
main.innerHTML=banner(name,params.get('parcours')||'Explorez les contenus et choisissez les ressources adaptées à vos besoins.')+(['formations','boutique','bibliotheque','blog'].includes(key)?`<div class="wrap">${rubriques(key,category)}</div>`:'')+`<div class="wrap page-content catalog"><aside class="sidebar"><h3>Affiner la recherche</h3><div><label for="filter-q">Mot-clé</label><input id="filter-q" name="q" value="${esc(params.get('q')||'')}" placeholder="Rechercher…"></div>${selectField('category','Catégorie',(categories[key]||[]).filter(x=>!x.startsWith('Tous')&&!x.startsWith('Toutes')),category)}${selectField('domain','Domaine',domains,params.get('domaine')||'')}${key==='formations'?`${selectField('level','Niveau',['Débutant','Intermédiaire','Intermédiaire / Avancé','Avancé'])}${selectField('audience','Public',['Tous publics','Étudiants','Professionnels','Entreprises'],params.get('public')||'')}${selectField('format','Format',['Vidéo + supports + cas pratiques','Lecture + quiz','Cours + cas pratiques'])}${selectField('duration','Durée',[...new Set(items(kind).map(i=>i.duration).filter(Boolean))])}${selectField('trainer','Formateur',[...new Set(items(kind).map(i=>i.trainer).filter(Boolean))])}${selectField('language','Langue',['Français'])}`:''}${selectField('price','Accès',['Gratuit','Payant'])}${key==='formations'?['attestation','cases','models'].map((k,n)=>`<label class="check"><input type="checkbox" name="${k}">${['Avec attestation','Avec cas pratiques','Avec modèles'][n]}</label>`).join(''):''}${key==='bibliotheque'?`<div><label>Juridiction<input name="court" placeholder="Toutes les juridictions"></label></div><div><label>Numéro<input name="number" placeholder="Référence"></label></div><div><label>Date<input type="date" name="date"></label></div>`:''}<button class="btn outline small" id="reset-filters">Réinitialiser</button></aside><div><div class="result-count" role="status"></div><div id="results" class="grid"></div></div></div>`;
const filter=()=>{const fields=Object.fromEntries($$('.sidebar [name]').map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]));let result=state.items.filter(i=>i.kind===kind||(i.placements||[]).some(p=>p.section===key)).filter(i=>{const q=fields.q?.toLowerCase()||'';if(q&&!JSON.stringify(i).toLowerCase().includes(q))return false;for(const k of ['domain','level','audience','format','duration','trainer','language','court','number','date'])if(fields[k]&&!(k==='domain'?(i.domain||i.category)===fields[k]:String(i[k]||'').includes(fields[k])))return false;if(fields.price==='Gratuit'&&i.price!==0)return false;if(fields.price==='Payant'&&!(i.price>0))return false;for(const k of ['attestation','cases','models'])if(fields[k]&&!i[k])return false;const cat=fields.category;if(cat==='Formations gratuites')return i.price===0;if(cat==='Formations à la une')return i.featured||(i.placements||[]).some(p=>p.section===key&&p.category===cat);if(cat&&cat!=='Nouvelles formations'&&i.category!==cat&&!(i.placements||[]).some(p=>p.section===key&&p.category===cat))return false;if(params.get('parcours')&&!(i.paths||[]).includes(params.get('parcours')))return false;return true;});$('.result-count').textContent=result.length+' résultat'+(result.length!==1?'s':'');$('#results').innerHTML=result.length?result.map(card).join(''):empty('Aucun résultat pour cette sélection.','Essayez un autre filtre. Les nouveaux contenus seront ajoutés par le cabinet.');};$$('.sidebar [name]').forEach(e=>e.addEventListener(e.tagName==='INPUT'&&e.type!=='checkbox'?'input':'change',filter));$('#reset-filters').onclick=()=>{$$('.sidebar [name]').forEach(e=>e.type==='checkbox'?e.checked=false:e.value='');params.delete('parcours');filter();};filter();}
function selectField(name,label,values,value=''){return `<div><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}"><option value="">Tous</option>${values.map(v=>`<option ${v===value?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div>`;}
function domainPage(d){if(!d){main.innerHTML=banner('Domaines de formation')+`<div class="wrap">${rubriques('formations','Domaines de formation')}</div>`+`<section class="section wrap"><div class="domain-grid">${domains.map(x=>`<a class="domain" href="#/domaine/${enc(x)}">${icon()}${x}</a>`).join('')}</div></section>`;return;}const result=state.items.filter(i=>i.category===d||i.domain===d);main.innerHTML=banner(d,'Formations, articles, documents, jurisprudence et cas pratiques associés à ce domaine.')+`<section class="section wrap"><div class="filter-tags">${(domainSubs[d]||[]).map(x=>`<a href="#/recherche?q=${enc(x)}">${x}</a>`).join('')}</div><div class="actions">${button('Voir les formations','#/formations?domaine='+enc(d))}${button('Rechercher des ressources','#/recherche?q='+enc(d),'outline')}</div><div class="grid" style="margin-top:30px">${result.length?result.map(card).join(''):empty()}</div></section>`;}
function pathPage(){main.innerHTML=banner('Parcours professionnels','Un parcours structuré autour des compétences de votre métier.')+`<div class="wrap">${rubriques('formations','Parcours professionnels')}</div>`+`<section class="section wrap"><div class="paths">${paths.map(p=>`<a class="path-card" href="#/formations?parcours=${enc(p)}"><span class="icon">${icon('case')}</span>${p}</a>`).join('')}</div></section>`;}
function community(key,params){const sub=params.get('categorie');main.innerHTML=banner(sub||labels[key],{etudiants:'Apprenez, révisez et préparez votre avenir professionnel.',professionnels:'Recherchez, consultez et approfondissez votre pratique.',entreprises:'Formez vos collaborateurs et accédez à la documentation professionnelle.'}[key])+`<section class="section wrap"><div class="two-col"><div><div class="eyebrow">VOTRE ESPACE DÉDIÉ</div><h2>${labels[key]}</h2><p>Retrouvez des contenus organisés pour votre profil et vos objectifs.</p><div class="actions">${button('Explorer les formations','#/formations?public='+enc(labels[key]))}${button(key==='entreprises'?'Demander un devis':'Contacter l’équipe','#/contact?objet='+enc(key==='entreprises'?'Demande de devis':sub||labels[key]),'outline')}</div></div>${rubriques(key,sub)}</div>${sub?`<div style="margin-top:35px"><h2>Ressources : ${esc(sub)}</h2><div class="grid">${state.items.filter(i=>JSON.stringify(i).toLowerCase().includes(sub.toLowerCase())).map(card).join('')||empty('La sélection sera enrichie prochainement.','Consultez le catalogue ou précisez votre besoin à l’équipe.')}</div></div>`:''}</section>`;}
async function detail(id){const token=pageToken;main.innerHTML=banner('Chargement du contenu…');const i=await api('item/'+enc(id));if(token!==pageToken)return;document.title=i.title+' | LEX ASSOCIÉS';const course=i.kind==='formation';const mods=i.modules||[];const completed=i.completed||[];const progress=mods.length?Math.round(completed.length/mods.length*100):0;main.innerHTML=banner(i.title,i.description)+`<div class="wrap page-content detail-grid"><div>${i.demo?'<div class="notice">Aperçu de la plateforme : ce contenu de présentation reste à valider par le cabinet.</div>':''}${i.body?`<div class="prose">${esc(i.body)}</div>`:''}${course?`<h2>Programme de la formation</h2>${i.access?`<p>${progress} % terminé</p><div class="progress-track"><span style="width:${progress}%"></span></div>`:''}${mods.map((m,n)=>`<details class="module"><summary>${completed.includes(m.id)?'✓ ':''}Module ${n+1} — ${esc(m.title)}</summary><div class="module-content">${i.access&&m.body?`${m.video?`<video controls preload="metadata" src="${safeUrl(m.video)}"></video>`:''}<div class="prose">${esc(m.body)}</div>${m.exercise?`<h3>Exercice / cas pratique</h3><p>${esc(m.exercise)}</p>`:''}<form data-module="${esc(m.id)}" data-course="${esc(id)}">${(m.quiz||[]).map((q,k)=>`<fieldset><legend>${esc(q.question)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="answer-${k}" value="${j}" required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}<button class="btn" ${completed.includes(m.id)?'disabled':''}>${completed.includes(m.id)?'Module terminé':'Valider ce module'}</button><div class="feedback" role="status"></div></form>${completed.includes(m.id)&&m.correction?`<details><summary>Voir la correction</summary><p>${esc(m.correction)}</p></details>`:''}`:`<p>${i.access?'Le contenu pédagogique de ce module sera publié prochainement.':'Connectez-vous et inscrivez-vous pour accéder aux contenus disponibles.'}</p>`}</div></details>`).join('')}${!mods.length?empty('Le programme détaillé sera ajouté prochainement.'):''}`:''}${i.kind==='event'?`<h2>Programme</h2><p>${esc(i.program||'Le programme et les intervenants seront confirmés par le cabinet.')}</p>`:''}${i.kind==='live'?i.video?`<video controls style="width:100%" src="${safeUrl(i.video)}"></video>`:empty('La vidéo sera publiée prochainement.'):''}${i.kind==='trainer'?`<h2>Biographie</h2><p>${esc(i.bio||'')}</p>`:''}${i.kind==='plan'?`<h2>Votre accès</h2><p>${esc(i.description)}</p><p>Les tarifs et les modalités détaillées seront confirmés avant toute souscription payante.</p>${button('Comparer les abonnements','#/abonnements','outline')}`:''}<h3 style="margin-top:30px">${course?'Supports pédagogiques':'Documents et ressources'}</h3>${i.files.length?i.files.map(f=>`<div class="list-row"><span>${esc(f.name)} · ${Math.round(f.size/1024)} Ko</span><a class="btn outline small" href="/api/file/${f.id}">Télécharger</a></div>`).join(''):'<p class="muted">Aucun fichier disponible pour le moment.</p>'}${i.features?`<ul>${i.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}${i.references?`<h3>Textes et références</h3><div class="prose">${esc(i.references)}</div>`:''}${i.related?.length?`<h2 style="margin-top:40px">Pour approfondir</h2><div class="grid">${state.items.filter(x=>i.related.includes(x.id)).map(card).join('')}</div>`:''}</div><aside class="detail-aside"><div class="eyebrow">${esc(i.category||i.kind)}</div><h2>${['formation','document','plan','event'].includes(i.kind)?money(i.price):'Votre ressource'}</h2><dl>${Object.entries({Niveau:i.level,Durée:i.duration,Modules:course?mods.length:null,Format:i.format,Formateur:i.trainer,Auteur:i.author,Langue:i.language,Accès:i.accessDuration,Attestation:course?(i.attestation?'Prévue selon les conditions du parcours':'Non prévue pour ce parcours'):null,Participants:i.participants,Évaluation:i.rating,Date:i.date?date(i.date):null,Heure:i.time,Lieu:i.location}).filter(([k,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${course&&i.price===0&&!i.access?`<button class="btn" data-action="enroll" data-id="${esc(id)}">Commencer gratuitement</button>`:''}${i.purchasable&&!i.demo?`<button class="btn" data-action="cart" data-id="${esc(id)}">${course?'Acheter la formation':'Ajouter au panier'}</button>`:''}${i.kind==='event'?`<button class="btn" data-action="event" data-id="${esc(id)}" ${!i.date||i.demo?'disabled':''}>S’inscrire à l’événement</button>`:''}${course&&i.access&&progress===100&&i.attestation&&!i.demo?`<button class="btn" data-action="certificate" data-id="${esc(id)}">Obtenir mon attestation</button>`:''}<button class="btn outline" data-action="favorite" data-id="${esc(id)}">Enregistrer dans mes favoris</button>${button('Demander des informations','#/contact?objet='+enc(i.title),'outline')}${course&&i.attestation?'<p class="tiny" style="margin-top:15px">L’attestation dépend de la validation du parcours et de l’évaluation définie par le cabinet.</p>':''}</aside></div>`;}
function searchPage(params){main.innerHTML=banner('Recherche juridique','Formations, modèles, articles, textes, jurisprudence et ouvrages.')+`<section class="section wrap"><form data-form="search" class="search-box"><input name="q" value="${esc(params.get('q')||'')}" placeholder="Que recherchez-vous ?" aria-label="Que recherchez-vous ?"><button class="btn">Rechercher</button></form><div class="form-grid" id="search-filters">${selectField('type','Type',['formation','article','document','resource','live','watch'])}${selectField('domain','Domaine',domains)}<div class="field"><label>Auteur<input name="author" placeholder="Tous les auteurs"></label></div><div class="field"><label>Date de publication<input name="date" type="date"></label></div>${selectField('access','Accès',['Gratuit','Premium'])}</div><div id="search-results" class="grid" style="margin-top:30px"></div></section>`;const render=()=>{const q=(params.get('q')||'').toLowerCase();const f=Object.fromEntries($$('#search-filters [name]').map(e=>[e.name,e.value]));const result=state.items.filter(i=>(!q||JSON.stringify(i).toLowerCase().includes(q))&&(!f.type||i.kind===f.type)&&(!f.domain||(i.domain||i.category)===f.domain)&&(!f.author||(i.author||i.trainer||'').toLowerCase().includes(f.author.toLowerCase()))&&(!f.date||i.date===f.date)&&(!f.access||(f.access==='Gratuit'?i.price===0:i.price>0)));$('#search-results').innerHTML=result.map(card).join('')||empty('Aucun résultat.','Essayez un autre mot-clé ou modifiez les filtres.');};$$('#search-filters [name]').forEach(e=>e.oninput=render);render();}
function authPage(register=false){if(state.user){location.hash='#/compte';return;}main.innerHTML=banner(register?'Créer mon compte':'Connexion')+`<section class="section wrap"><form class="form-card" data-form="${register?'register':'login'}"><h2>${register?'Bienvenue chez LEX ASSOCIÉS':'Retrouvez votre espace'}</h2>${register?'<div class="field"><label for="auth-name">Nom complet</label><input id="auth-name" name="name" autocomplete="name" required maxlength="160"></div>':''}<div class="field"><label for="auth-email">E-mail</label><input id="auth-email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="auth-pass">Mot de passe${register?' (10 caractères minimum)':''}</label><input id="auth-pass" name="password" type="password" minlength="${register?10:1}" autocomplete="${register?'new-password':'current-password'}" required maxlength="256"></div><button class="btn">${register?'Créer mon compte':'Me connecter'}</button><div class="feedback" role="status"></div><p class="form-switch">${register?'Déjà inscrit ? <a class="text-link" href="#/connexion">Se connecter</a>':'Pas encore de compte ? <a class="text-link" href="#/inscription">Créer un compte</a>'}</p></form></section>`;}
function contactPage(params){main.innerHTML=banner('Contact','Notre équipe est à votre écoute pour vos formations et vos projets juridiques.')+`<div class="wrap section two-col" style="align-items:start"><div><div class="eyebrow">LEX ASSOCIÉS</div><h2>Parlons de votre besoin.</h2><p>Une formation, un document, un accompagnement ou un rendez-vous : adressez votre demande au cabinet.</p><p class="muted">Les coordonnées directes et les réseaux sociaux seront ajoutés après confirmation par le cabinet.</p><a class="text-link" href="#/faq">Consulter les questions fréquentes</a></div><form data-form="contact"><div class="form-grid">${[['first','Prénom','text'],['last','Nom','text'],['email','E-mail','email'],['phone','Téléphone','tel']].map(([n,l,t])=>`<div class="field"><label for="contact-${n}">${l}</label><input id="contact-${n}" name="${n}" type="${t}" ${n!=='phone'?'required':''}></div>`).join('')}<div class="field full"><label for="contact-subject">Objet</label><input id="contact-subject" name="subject" required value="${esc(params.get('objet')||'')}"></div><div class="field full"><label for="contact-message">Message</label><textarea id="contact-message" name="message" required maxlength="5000"></textarea></div></div><p class="tiny">Votre demande est enregistrée dans l’espace du cabinet. Aucun paiement n’est effectué depuis ce formulaire.</p><button class="btn">Envoyer ma demande</button><div class="feedback" role="status"></div></form></div>`;}
function aboutPage(params){const sub=params.get('categorie')||'Qui sommes-nous ?';const text={'Qui sommes-nous ?':'LEX ASSOCIÉS est un cabinet juridique spécialisé dans l’encadrement et l’assistance des particuliers et des petites, moyennes et grandes entreprises. Sa plateforme réunit formation, documentation et pratique du droit en Côte d’Ivoire et dans l’espace OHADA.','Notre mission':'Rendre les connaissances juridiques accessibles et relier l’apprentissage à la pratique professionnelle.','Notre vision':'Un espace commun pour apprendre le droit, comprendre le droit et pratiquer le droit.','Nos valeurs':'Une démarche fondée sur la clarté des contenus, la rigueur de leur préparation et leur utilité pour les apprenants.','Notre équipe':'Le cabinet réunit des juristes-conseils, des avocats, des commissaires de justice et des notaires. Les profils nominatifs et leurs biographies seront présentés après validation par le cabinet.','Nos partenaires':'Les partenaires du cabinet seront présentés dans cet espace après validation.','Nos domaines d’expertise':'Droit des affaires, droit immobilier, droit social, droit civil, droit minier, fiscalité et droit pénal.','Pourquoi LEX ASSOCIÉS ?':'La plateforme relie les cours, les ressources documentaires et les outils de pratique dans un même parcours d’apprentissage.'};main.innerHTML=banner('À propos de LEX ASSOCIÉS','Apprendre. Comprendre. Pratiquer.')+`<div class="wrap page-content about-page">${categories.apropos.map((heading,n)=>`<section class="about-section" aria-labelledby="about-${n}"><div class="eyebrow">LEX ASSOCIÉS</div><h2 id="about-${n}">${esc(heading)}</h2>${heading==='Nos formateurs'?`${items('trainer').length?`<div class="grid">${items('trainer').map(card).join('')}</div>`:'<p class="prose">Les profils de nos formateurs, leurs domaines d’expertise et leurs formations seront présentés ici après validation par le cabinet.</p>'}<a class="text-link" href="#/formateurs">Voir les profils des formateurs</a>`:`<p class="prose">${esc(text[heading]||'')}</p>`}</section>`).join('')}<div class="actions">${button('Nos formations','#/formations')}${button('Contacter l’équipe','#/contact','outline')}</div></div>`;}

function subscriptionPage(){const features=['Articles','Bibliothèque','Documents','Formations','Webinaires','Réductions','Téléchargements','Veille','Supports premium','Comptes collaborateurs'];main.innerHTML=banner('Abonnements','Choisissez l’accès adapté à votre usage de la plateforme.')+`<div class="wrap page-content">${plans()}<h2 style="margin-top:45px">Comparer les offres</h2><p class="notice">Les tarifs, quotas et conditions des offres payantes sont en cours de définition. Aucune souscription payante n’est activée.</p><div class="table-scroll"><table><thead><tr><th>Services</th>${items('plan').map(i=>`<th>${esc(i.title)}</th>`).join('')}</tr></thead><tbody>${features.map(f=>`<tr><th>${f}</th>${items('plan').map(i=>`<td>${i.price===0?(['Articles','Formations'].includes(f)?'Contenus gratuits':'Selon les contenus'):'À confirmer'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
function faqPage(){const faq=[['Questions générales',[['Qu’est-ce que LEX ASSOCIÉS ?','Une plateforme dédiée à la formation, à la documentation et à la pratique du droit.'],['Qui peut utiliser la plateforme ?','Étudiants, professionnels, entreprises et toute personne souhaitant accéder aux ressources disponibles.'],['Comment créer un compte ?','Ouvrez « Créer mon compte », indiquez votre nom, votre e-mail et un mot de passe personnel.']] ],['Formations',[['Comment accéder à une formation ?','Ouvrez sa fiche. Les parcours gratuits disponibles proposent le bouton « Commencer gratuitement ». Les achats seront accessibles après activation du paiement.'],['Combien de temps ai-je accès à une formation ?','La durée d’accès est indiquée sur la fiche de chaque formation lorsqu’elle est définie.'],['Puis-je suivre une formation à mon rythme ?','Les modules publiés sont accessibles depuis votre espace de formation. Les classes virtuelles suivent leur calendrier.'],['Les formations donnent-elles lieu à une attestation ?','La fiche indique si une attestation est prévue. Sa délivrance dépend des conditions et de l’évaluation validées par le cabinet.'],['Puis-je télécharger les supports ?','Les fichiers disponibles apparaissent dans la fiche du contenu. Un compte et, le cas échéant, un accès autorisé sont nécessaires.']] ],['Boutique',[['Comment acheter un document ?','Les documents commercialisables peuvent être ajoutés au panier. Le paiement est pour le moment désactivé.'],['Les documents sont-ils modifiables ?','Le format et les éléments inclus sont précisés dans chaque fiche.'],['Comment télécharger mon achat ?','Les fichiers autorisés seront accessibles dans votre compte après validation effective de l’achat.']] ],['Abonnements',[['Quels sont les abonnements ?','Gratuit, Essentiel, Professionnel, Premium et Entreprise. Leurs conditions détaillées restent à confirmer.'],['Puis-je résilier ou changer d’offre ?','Les modalités seront précisées dans les conditions de vente avant activation des abonnements payants.']] ],['Entreprises',[['Peut-on inscrire plusieurs collaborateurs ?','Adressez une demande de devis au cabinet en précisant le nombre de personnes et les objectifs.'],['Proposez-vous des formations sur mesure ?','L’espace Entreprises permet de transmettre vos besoins pour étude par le cabinet.']]]];main.innerHTML=banner('Questions fréquentes')+`<section class="section wrap faq">${faq.map(([t,rows])=>`<h2 style="margin-top:30px">${t}</h2>${rows.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}`).join('')}</section>`;}
async function accountPage(params){if(!state.user){location.hash='#/connexion';return;}const data=await api('account');const tab=params.get('onglet')||'Tableau de bord';const tabs=['Tableau de bord','Mes formations','Ma progression','Mes attestations','Mes documents','Mes téléchargements','Mes favoris','Mes commandes','Mes factures','Mes abonnements','Mes événements','Notifications','Mon profil','Paramètres'];const own=data.enrollments.map(e=>state.items.find(i=>i.id===e.item_id)).filter(Boolean);let html='';
if(tab==='Tableau de bord')html=`<h2>Bienvenue, ${esc(state.user.name)}.</h2><p>Retrouvez vos contenus et reprenez votre apprentissage.</p><div class="stats"><div class="stat"><b>${own.length}</b>Formations</div><div class="stat"><b>${data.favorites.length}</b>Favoris</div><div class="stat"><b>${data.progress.length}</b>Modules terminés</div></div><div class="grid">${own.slice(0,3).map(card).join('')||empty('Votre parcours commence ici.','Découvrez le catalogue et commencez un parcours gratuit.')}</div>`;
else if(['Mes formations','Ma progression'].includes(tab))html=`<h2>${tab}</h2>${own.map(i=>{let done=data.progress.filter(p=>p.item_id===i.id).length;return `<div class="list-row"><div><h3>${esc(i.title)}</h3><p>${done} / ${(i.modules||[]).length} modules terminés</p></div>${button('Reprendre','#/contenu/'+i.id,'small')}</div>`;}).join('')||empty('Aucune formation commencée.')}`;
else if(tab==='Mes attestations')html=`<h2>Mes attestations</h2>${data.certificates.map(c=>`<div class="list-row"><div><h3>${esc(c.title)}</h3><p>${date(c.created)}</p></div><a class="btn outline small" href="/api/certificate/${c.id}">Télécharger l’attestation</a></div>`).join('')||empty('Aucune attestation délivrée.','Terminez un parcours ouvrant droit à une attestation et validez ses évaluations.')}`;
else if(tab==='Mes favoris')html=`<h2>Mes favoris</h2>${data.favorites.map(id=>{const i=state.items.find(x=>x.id===id);return i?`<div class="list-row"><a href="#/contenu/${id}">${esc(i.title)}</a><button class="text-link" data-action="unfavorite" data-id="${id}">Retirer</button></div>`:'';}).join('')||empty('Aucun favori enregistré.')}`;
else if(tab==='Mes commandes')html=`<h2>Mes commandes</h2>${data.orders.map(o=>`<div class="list-row"><div><h3>Commande ${esc(o.id.slice(0,8))}</h3><p>${date(o.created)} · En attente de paiement</p><p>${JSON.parse(o.lines).map(l=>esc(l.title)).join(' · ')}</p></div><b>${money(o.total)}</b></div>`).join('')||empty('Aucune commande.')}`;
else if(tab==='Mes téléchargements')html=`<h2>Mes téléchargements</h2>${data.downloads.map(d=>`<div class="list-row"><span>${esc(d.name)}</span><span>${date(d.created)}</span></div>`).join('')||empty('Aucun téléchargement.')}`;
else if(tab==='Mes événements')html=`<h2>Mes événements</h2><div class="grid">${state.items.filter(i=>data.events.includes(i.id)).map(card).join('')||empty('Aucune inscription à un événement.')}</div>`;
else if(tab==='Notifications')html=`<h2>Notifications</h2><button class="btn outline small" data-action="read-notifications">Tout marquer comme lu</button>${data.notifications.map(n=>`<div class="list-row"><a href="${esc(n.url)}">${n.seen?'':'● '}${esc(n.message)}</a><span>${date(n.created)}</span></div>`).join('')||'<p style="margin-top:20px">Aucune notification pour le moment.</p>'}`;
else if(['Mon profil','Paramètres'].includes(tab))html=`<h2>${tab}</h2><form data-form="profile" class="form-card"><div class="field"><label>Nom complet<input name="name" value="${esc(state.user.name)}" required></label></div><p class="tiny">${esc(state.user.email)}</p>${tab==='Paramètres'?'<h3>Changer de mot de passe</h3><label>Mot de passe actuel<input type="password" name="current_password" autocomplete="current-password"></label><label>Nouveau mot de passe<input type="password" name="new_password" minlength="10" autocomplete="new-password"></label>':''}<button class="btn">Enregistrer</button><div class="feedback" role="status"></div></form>`;
else html=`<h2>${tab}</h2>${empty(tab==='Mes attestations'?'Aucune attestation délivrée.':tab==='Mes factures'?'Aucune facture.':tab==='Mes abonnements'?'Accès gratuit actif.':'Aucun document acheté.',tab==='Mes attestations'?'Les attestations seront délivrées après validation des parcours concernés par le cabinet.':tab==='Mes factures'?'Aucun paiement n’a été encaissé.':tab==='Mes abonnements'?'Les offres payantes seront disponibles après confirmation de leurs conditions.':'Les documents disponibles seront associés à votre compte après un achat confirmé.')}`;
main.innerHTML=banner('Mon compte')+`<div class="wrap page-content account-layout"><aside class="sidebar">${tabs.map(t=>`<a class="${tab===t?'active':''}" href="#/compte?onglet=${enc(t)}">${t}</a>`).join('')}${['owner','admin','editor'].includes(state.user.role)?'<a href="#/administration">Administration</a>':''}<button class="text-link" data-action="logout" style="margin-top:20px">Se déconnecter</button></aside><div>${html}</div></div>`;}
async function cartPage(checkout=false){if(!state.user){location.hash='#/connexion';return;}const a=await api('account');const lines=a.cart.map(c=>({...c,item:state.items.find(i=>i.id===c.item_id)})).filter(x=>x.item);const total=lines.reduce((s,l)=>s+(l.item.price||0)*l.quantity,0);main.innerHTML=banner(checkout?'Paiement':'Mon panier')+`<div class="wrap page-content">${checkout?'<div class="stage-list"><span>1. Identification</span><span>2. Récapitulatif</span><span class="current">3. Mode de paiement</span><span>4. Confirmation</span><span>5. Accès</span></div>':''}${lines.map(l=>`<div class="list-row"><div><h3>${esc(l.item.title)}</h3><p>${money(l.item.price)} × ${l.quantity}</p></div><div class="actions"><label class="tiny">Quantité <input style="width:75px" type="number" min="1" max="10" value="${l.quantity}" data-quantity="${l.item.id}" ${checkout?'disabled':''}></label>${!checkout?`<button class="text-link" data-action="remove-cart" data-id="${l.item.id}">Retirer</button>`:''}</div></div>`).join('')||empty('Votre panier est vide.','Parcourez les formations et les documents disponibles.')}<div class="cart-total">Total : ${money(total)}</div>${lines.length?checkout?`<div class="notice">Le prestataire de paiement reste à définir. Aucun paiement n’est possible actuellement. Vous pouvez enregistrer votre commande en attente ; aucun accès payant ne sera débloqué.</div><button class="btn" data-action="order">Enregistrer la commande en attente</button>`:button('Passer au paiement','#/paiement'):''}</div>`;}
async function adminPage(params){if(!state.user){location.hash='#/connexion';return;}if(!['owner','admin','editor'].includes(state.user.role)){main.innerHTML=banner('Accès réservé')+`<section class="wrap section">${empty('Cet espace est réservé à l’administration.')}</section>`;return;}const d=await api('admin');const tab=params.get('onglet')||'Contenus';main.innerHTML=adminLayout(tab);const box=$('#admin-content');if(tab==='Contenus'){box.innerHTML=`<div class="account-heading"><h2>Contenus du site</h2><button class="btn" id="new-item">Ajouter un contenu</button></div><div class="notice">Les éléments « Aperçu » sont des exemples. Ajoutez les contenus validés, leurs supports et leurs conditions avant de les commercialiser.</div>${d.items.map(i=>`<div class="list-row"><div><h3>${esc(i.title)}</h3><p>${esc(i.kind)} · ${esc(i.status)}${i.demo?' · Aperçu':''}</p></div><button class="btn outline small" data-edit="${esc(i.id)}">Modifier</button></div>`).join('')}`;$('#new-item').onclick=()=>editor({kind:'article',status:'draft',modules:[],price:0});$$('[data-edit]').forEach(b=>b.onclick=()=>editor(d.items.find(i=>i.id===b.dataset.edit)));}
else if(tab==='Demandes')box.innerHTML=`<h2>Demandes reçues</h2>${d.messages.map(m=>`<article class="card" style="margin-bottom:20px"><div class="body"><h3>${esc(m.subject)}</h3><p>${esc(m.name)} · ${esc(m.email)} · ${esc(m.phone)}</p><p class="prose">${esc(m.body)}</p><div class="list-row"><span>${date(m.created)} · ${m.status==='processed'?'Traité':'Nouveau'}</span>${m.status!=='processed'?`<button class="text-link" data-message="${m.id}">Marquer comme traité</button>`:''}</div></div></article>`).join('')||'<p>Aucune demande.</p>'}`;
else if(tab==='Newsletter')box.innerHTML=`<h2>Inscriptions à la newsletter</h2><p class="notice">Les inscriptions sont enregistrées. L’envoi de campagnes reste à relier à un service de messagerie.</p>${d.newsletter.map(n=>`<div class="list-row"><div><b>${esc(n.name)}</b><p>${esc(n.email)}</p><p>${esc(JSON.parse(n.interests).join(', '))}</p></div><button class="text-link" data-unsubscribe="${esc(n.email)}">Désinscrire</button></div>`).join('')||'<p>Aucune inscription.</p>'}`;
else if(tab==='Commandes')box.innerHTML=`<h2>Commandes</h2><p class="notice">Aucun encaissement automatique n’est activé. Les commandes restent en attente.</p>${d.orders.map(o=>`<div class="list-row"><span>${esc(o.id)} · ${date(o.created)}</span><span>${money(o.total)} · ${esc(o.status)}</span></div>`).join('')||'<p>Aucune commande.</p>'}`;
else box.innerHTML=`<h2>Utilisateurs</h2>${d.users.map(u=>`<div class="list-row"><span>${esc(u.name)} · ${esc(u.email)}</span><span>${esc(u.role)}</span></div>`).join('')}`;
$$('[data-message]').forEach(b=>b.onclick=async()=>{await api('admin/message',{id:b.dataset.message});render();});$$('[data-unsubscribe]').forEach(b=>b.onclick=async()=>{await api('admin/newsletter-delete',{email:b.dataset.unsubscribe});render();});}
function editor(item){main.innerHTML=banner(item.id?'Modifier le contenu':'Nouveau contenu')+`<div class="wrap page-content"><a class="text-link" href="#/administration">Retour à l’administration</a><form id="editor-form" class="editor" style="margin-top:25px">${selectField('kind','Type de contenu',['formation','document','resource','article','event','live','trainer','plan','watch'],item.kind)}${selectField('status','Publication',['draft','published','archived'],item.status)}${[['title','Titre'],['category','Catégorie'],['domain','Domaine'],['author','Auteur'],['trainer','Formateur'],['image','Image (adresse HTTPS ou assets/…)'],['level','Niveau'],['audience','Public'],['duration','Durée'],['format','Format'],['language','Langue'],['accessDuration','Durée d’accès'],['date','Date (AAAA-MM-JJ)'],['time','Heure'],['location','Lieu / lien de réunion'],['video','Vidéo (fichier HTTPS)'],['price','Prix en FCFA'],['capacity','Places disponibles']].map(([n,l])=>`<div class="field"><label>${l}<input name="${n}" ${n==='title'?'required':''} ${['price','capacity'].includes(n)?'type="number" min="0"':''} value="${esc(item[n]??'')}"></label></div>`).join('')}<div class="field full"><label>Description courte<textarea name="description">${esc(item.description||'')}</textarea></label></div><div class="field full"><label>Contenu / biographie / présentation<textarea name="body" style="min-height:220px">${esc(item.body||'')}</textarea></label></div><div class="field full"><label>Textes cités et références<textarea name="references">${esc(item.references||'')}</textarea></label></div><div class="field full"><label>Contenus associés (identifiants séparés par une virgule)<input name="related" value="${esc((item.related||[]).join(', '))}"></label></div><div class="field full"><label>Parcours associés (noms séparés par une virgule)<input name="paths" value="${esc((item.paths||[]).join(', '))}"></label></div><div class="interests full">${[['demo','Contenu de présentation'],['featured','À la une'],['purchasable','Disponible à l’achat'],['attestation','Attestation prévue'],['cases','Cas pratiques'],['models','Modèles inclus']].map(([n,l])=>`<label><input type="checkbox" name="${n}" ${item[n]?'checked':''}>${l}</label>`).join('')}</div><div class="full"><h2>Modules de formation</h2><p class="tiny">Ajoutez les modules dans leur ordre de lecture, puis enregistrez le contenu.</p><div id="module-editors"></div><button type="button" class="btn outline small" id="add-module">Ajouter un module</button></div><div class="full"><button class="btn">Enregistrer le contenu</button><div class="feedback" role="status"></div></div></form>${item.id?`<form id="upload-form" class="upload-row"><h3>Joindre un support ou un document</h3><p class="tiny">PDF, Word, Excel, PowerPoint, texte, image ou MP4. 10 Mo maximum. Le téléchargement est contrôlé par les droits du compte.</p><input type="file" name="file" required accept=".pdf,.docx,.xlsx,.pptx,.txt,.png,.jpg,.jpeg,.mp4"><button class="btn" style="margin-top:15px">Ajouter le fichier</button><div class="feedback" role="status"></div></form>`:''}</div>`;
const modbox=$('#module-editors');function addModule(m={}){const el=document.createElement('div');el.className='module module-editor';el.dataset.id=m.id||'module-'+crypto.randomUUID();el.innerHTML=`<div class="module-content"><label>Titre du module<input name="mtitle" value="${esc(m.title||'')}" required></label><label>Contenu pédagogique<textarea name="mbody">${esc(m.body||'')}</textarea></label><label>Vidéo (URL HTTPS)<input name="mvideo" value="${esc(m.video||'')}"></label><label>Cas pratique / exercice<textarea name="mexercise">${esc(m.exercise||'')}</textarea></label><label>Correction<textarea name="mcorrection">${esc(m.correction||'')}</textarea></label><label>Question du quiz<input name="mquestion" value="${esc(m.quiz?.[0]?.question||'')}"></label><div class="form-grid">${[0,1,2].map(n=>`<label>Réponse ${n+1}<input name="moption${n}" value="${esc(m.quiz?.[0]?.options?.[n]||'')}"></label>`).join('')}<label>Bonne réponse<select name="mcorrect">${[0,1,2].map(n=>`<option value="${n}" ${m.quiz?.[0]?.correct===n?'selected':''}>Réponse ${n+1}</option>`).join('')}</select></label></div><button type="button" class="text-link remove-module" style="margin-top:15px">Retirer ce module</button></div>`;modbox.append(el);$('.remove-module',el).onclick=()=>el.remove();} (item.modules||[]).forEach(addModule);$('#add-module').onclick=()=>addModule();
$('#editor-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const values=Object.fromEntries(new FormData(f));const p={...item,...values};for(const k of ['demo','featured','purchasable','attestation','cases','models'])p[k]=f.elements[k].checked;p.price=values.price===''?null:Number(values.price);p.capacity=values.capacity?Number(values.capacity):null;p.related=values.related.split(',').map(s=>s.trim()).filter(Boolean);p.paths=values.paths.split(',').map(s=>s.trim()).filter(Boolean);p.modules=$$('.module-editor',f).map(el=>{const v=n=>$(`[name="${n}"]`,el).value;return {id:el.dataset.id,title:v('mtitle'),body:v('mbody'),video:v('mvideo'),exercise:v('mexercise'),correction:v('mcorrection'),quiz:v('mquestion')?[{question:v('mquestion'),options:[0,1,2].map(n=>v('moption'+n)),correct:Number(v('mcorrect'))},...((item.modules||[]).find(m=>m.id===el.dataset.id)?.quiz||[]).slice(1)]:[]};});const result=await api('admin/item',{item:p});await refresh();toast('Contenu enregistré.');editor({...p,id:result.id});}catch(err){feedback(f,err.message,true);}};
if($('#upload-form'))$('#upload-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const file=f.elements.file.files[0];if(file.size>10*1024*1024)throw Error('10 Mo maximum.');const content=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result.split(',')[1]);reader.onerror=rej;reader.readAsDataURL(file);});await api('admin/upload',{item_id:item.id,name:file.name,content});feedback(f,'Fichier ajouté.');f.reset();}catch(err){feedback(f,err.message,true);}};}
function legalPage(params){const name=params.get('type')||'Informations juridiques';main.innerHTML=banner(name)+`<section class="section wrap"><p>Cette plateforme est actuellement en phase de préparation locale. Les mentions légales, les conditions de vente et les politiques définitives seront publiées après validation par LEX ASSOCIÉS.</p>${name==='Confidentialité'?'<p>Les comptes, demandes de contact et inscriptions sont conservés dans la base locale de la plateforme. Aucun service d’envoi de campagnes ni prestataire de paiement n’est connecté. Vous pouvez contacter le cabinet pour demander la suppression de vos informations.</p>':name==='Cookies'?'<p>Un cookie de session est utilisé pour maintenir votre connexion. Une mesure d’audience locale et facultative est proposée avec votre accord : pages publiques consultées, liens suivis et temps actif. Aucun texte saisi dans les formulaires, adresse IP ou identifiant de compte n’est enregistré dans les statistiques. Les événements sont conservés 90 jours, et l’identifiant de navigateur est renouvelé chaque mois. Vous pouvez modifier votre choix via les préférences de confidentialité en bas de page.</p>':'<p>Aucun encaissement n’est activé. Les coordonnées de l’éditeur et les conditions applicables seront ajoutées avant ouverture commerciale.</p>'}${button('Contacter le cabinet','#/contact','outline')}</section>`;}
function feedback(form,message,error=false){const el=$('.feedback',form);el.className='feedback '+(error?'error':'success');el.textContent=message;}
async function refresh(){state=await api('bootstrap');shell();}
async function render(){pageToken++;const token=pageToken;const raw=currentRoute();const [path,query='']=raw.split('?');const params=new URLSearchParams(query);if(raw==='main'){document.getElementById('main').focus();return;}const key=path.split('/')[1]||'';$$('header details').forEach(d=>d.open=false);$('.nav-row')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false');document.title='LEX ASSOCIÉS — Apprendre. Comprendre. Pratiquer.';try{if(!key)home();else if(['formations','boutique','bibliotheque','blog','evenements','live','veille','formateurs'].includes(key))catalog(key,params);else if(key==='domaine')domainPage(decodeURIComponent(path.split('/').slice(2).join('/')));else if(key==='contenu')await detail(decodeURIComponent(path.split('/')[2]||''));else if(['etudiants','professionnels','entreprises'].includes(key))community(key,params);else if(key==='recherche')searchPage(params);else if(key==='connexion'||key==='inscription')authPage(key==='inscription');else if(key==='compte')await accountPage(params);else if(key==='panier'||key==='paiement')await cartPage(key==='paiement');else if(key==='contact')contactPage(params);else if(key==='apropos')aboutPage(params);else if(key==='abonnements')subscriptionPage();else if(key==='faq')faqPage();else if(key==='newsletter')main.innerHTML=banner('Newsletter')+newsletter();else if(key==='recuperation')recoveryPage(params);else if(key==='administration')await adminPage(params);else if(key==='juridique')legalPage(params);else main.innerHTML=banner('Page introuvable')+`<section class="section wrap">${button('Revenir à l’accueil','#/')}</section>`;if(token===pageToken){window.scrollTo(0,0);updatePageSEO();}}catch(err){main.innerHTML=banner('Impossible de charger cette page')+`<section class="section wrap"><p>${esc(err.message)}</p><button class="btn" id="retry">Réessayer</button></section>`;$('#retry').onclick=render;}}
document.addEventListener('submit',async e=>{const f=e.target;const type=f.dataset.form;if(!type&&!f.dataset.module)return;e.preventDefault();const submit=f.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{const v=Object.fromEntries(new FormData(f));if(f.dataset.module){const answers={};for(const [k,val] of Object.entries(v))if(k.startsWith('answer-'))answers[k.slice(7)]=Number(val);await api('progress',{id:f.dataset.course,module:f.dataset.module,answers});toast('Module validé. Votre progression est enregistrée.');await render();return;}if(type==='search'){location.hash='#/recherche?q='+enc(v.q||'');return;}if(type==='login'||type==='register'){await api(type,v);await refresh();location.hash='#/compte';return;}if(type==='contact'){v.name=v.first+' '+v.last;const r=await api('contact',v);feedback(f,r.message);f.reset();return;}if(type==='newsletter'){v.interests=new FormData(f).getAll('interest');v.consent=f.elements.consent.checked;const r=await api('newsletter',v);feedback(f,r.message);f.reset();return;}if(type==='profile'){await api('profile',v);await refresh();feedback(f,'Modifications enregistrées.');if(v.new_password)location.hash='#/connexion';return;}}catch(err){feedback(f,err.message,true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(!state.user&&action!=='logout'){location.hash='#/connexion';return;}b.disabled=true;try{if(action==='logout'){await api('logout',{});await refresh();location.hash='#/';return;}if(action==='certificate'){await api('certificate',{id:b.dataset.id});toast('Votre attestation est disponible dans votre compte.');location.hash='#/compte?onglet=Mes%20attestations';return;}if(action==='order'){const r=await api('order',{});toast(r.message);location.hash='#/compte?onglet=Mes%20commandes';return;}if(action==='read-notifications'){await api('notifications',{});await render();return;}const route={unfavorite:'favorite','remove-cart':'cart'}[action]||action;await api(route,{id:b.dataset.id,remove:['unfavorite','remove-cart'].includes(action)});toast({favorite:'Ajouté aux favoris.',unfavorite:'Favori retiré.',cart:'Ajouté au panier.',enroll:'Inscription enregistrée.',event:'Inscription confirmée.','remove-cart':'Article retiré.'}[action]||'Enregistré.');if(action==='cart')location.hash='#/panier';else if(action!=='favorite')await render();}catch(err){toast(err.message);}finally{b.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.dataset.quantity){try{await api('cart',{id:e.target.dataset.quantity,quantity:Number(e.target.value)});await render();}catch(err){toast(err.message);}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('header details').forEach(d=>d.open=false);});
$('#modal .close').onclick=()=>$('#modal').close();
window.addEventListener('hashchange',render);
